import uuid
from datetime import datetime
from typing import Any

from geoalchemy2 import Geography, Geometry
from sqlalchemy import (
    CheckConstraint,
    Computed,
    DateTime,
    Double,
    Index,
    MetaData,
    String,
    Uuid,
    func,
)
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column

NAMING = {
    "ix": "ix_%(table_name)s_%(column_0_N_name)s",
    "uq": "uq_%(table_name)s_%(column_0_N_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "pk": "pk_%(table_name)s",
}

# generated by PostGIS from lat/lon/radius_m; the envelope carries the GiST index
CENTER_SQL = "ST_Point(lon, lat, 4326)::geography"
ENVELOPE_SQL = "geozone_envelope(lat, lon, radius_m)"


class Base(DeclarativeBase):
    metadata = MetaData(naming_convention=NAMING)


class Geozone(Base):
    __tablename__ = "geozones"
    __table_args__ = (
        CheckConstraint("lat BETWEEN -90 AND 90", name="lat_range"),
        CheckConstraint("lon BETWEEN -180 AND 180", name="lon_range"),
        CheckConstraint("radius_m > 0 AND radius_m <= 100000", name="radius_range"),
        Index("ix_geozones_owner_created", "owner_id", "created_at"),
        Index("ix_geozones_envelope", "envelope", postgresql_using="gist"),
    )

    id: Mapped[uuid.UUID] = mapped_column(Uuid, primary_key=True)
    owner_id: Mapped[str] = mapped_column(String(64))
    name: Mapped[str] = mapped_column(String(100))
    latitude: Mapped[float] = mapped_column("lat", Double)
    longitude: Mapped[float] = mapped_column("lon", Double)
    radius_m: Mapped[float] = mapped_column(Double)
    center: Mapped[Any] = mapped_column(
        Geography("POINT", srid=4326, spatial_index=False),
        Computed(CENTER_SQL, persisted=True),
        deferred=True,
        deferred_raiseload=True,
    )
    envelope: Mapped[Any] = mapped_column(
        Geometry("POLYGON", srid=4326, spatial_index=False),
        Computed(ENVELOPE_SQL, persisted=True),
        deferred=True,
        deferred_raiseload=True,
    )
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True))
    updated_at: Mapped[datetime] = mapped_column(DateTime(timezone=True))


class DevicePosition(Base):
    """Latest accepted position per device (no history is kept)."""

    __tablename__ = "device_positions"
    __table_args__ = (
        Index("ix_device_positions_position", "position", postgresql_using="gist"),
    )

    device_id: Mapped[str] = mapped_column(String(128), primary_key=True)
    position: Mapped[Any] = mapped_column(
        Geography("POINT", srid=4326, spatial_index=False)
    )
    reported_at: Mapped[datetime] = mapped_column(DateTime(timezone=True))
    received_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.now()
    )
